CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user',paid BOOLEAN NOT NULL DEFAULT FALSE,subscription_status TEXT NOT NULL DEFAULT 'free',paystack_customer_code TEXT,paystack_subscription_code TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS tracks(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,prompt TEXT NOT NULL,genre TEXT NOT NULL,vibe TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',provider_id TEXT,audio_url TEXT,duration INTEGER,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,reference TEXT UNIQUE NOT NULL,amount INTEGER,currency TEXT,status TEXT NOT NULL,raw JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());